    },
    {
      "title": "EASA June 2026 Revision: Easy Access Rules for Unmanned ...",
      "url": "https://registry.deploy.report/regulations/easa-uas-easy-access-rules-june-2026",
      "content": "Aug 23, 2026 · EASA published the June 2026 revision of the Easy Access Rules for UAS, consolidating Commission Implementing Regulation (EU) 2019/947 on UAS operations with updated AMC and Guidance Material. Provides harmonized regulatory framework for drone operations across EU."
    },
    {
      "title": "Easy Access Rules for Unmanned Aircraft Systems - drones.gov.cy",
      "url": "https://drones.gov.cy/wp-content/uploads/2025/08/EAR_UAS_Jul24.pdf",
