    },
    {
      "title": "EASA publishes updated Easy Access Rules including SORA 2.5",
      "url": "https://www.dronewatch.eu/easa-publishes-updated-easy-access-rules-including-sora-2-5/",
      "content": "Jul 2, 2026 · What are the Easy Access Rules? The Easy Access Rules are a consolidated publication compiled by EASA, bringing together all applicable European drone legislation along with official explanations and interpretations."
    }
  ]
}

